    AsunaHentai token;
    address public owner = makeAddr("owner");
    address public attacker = makeAddr("attacker");

    function setUp() public {
        vm.startPrank(owner);

        // Mock router and factory calls
        address routerAddr = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        address mockFactory = address(0xFaC7Abc0d5375a214421e98001001FaC7);
        address mockPair = address(0xD1480d0A0DAa6c80009901234);
        address mockWETH = address(0x000000000000000000000000000000000000dEaD);

        // Mock router factory()
        vm.mockCall(
            routerAddr,
            abi.encodeWithSelector(bytes4(keccak256("factory()"))),
            abi.encode(mockFactory)
        );

        // Mock router WETH()
        vm.mockCall(
            routerAddr,
            abi.encodeWithSelector(bytes4(keccak256("WETH()"))),
            abi.encode(mockWETH)
        );

        // Mock factory createPair() for any arguments
        vm.mockCall(
            mockFactory,
            abi.encodeWithSelector(bytes4(keccak256("createPair(address,address)"))),
            abi.encode(mockPair)
        );

        token = new AsunaHentai();
        vm.stopPrank();
    }

    function test_lockAndUnlock() public {
        // Owner locks the contract
        vm.prank(owner);
        token.lock(1 days);
        assertEq(token.owner(), address(0), "Contract should be locked after owner calls lock()");

        // Attempt immediate unlock (before lock expires)
        vm.prank(owner);
        vm.expectRevert("Contract is locked until 7 days");
        token.unlock();

        // Advance time past lock duration
        vm.warp(block.timestamp + 1 days + 1 seconds);
        vm.prank(owner);
        token.unlock();

        // Verify ownership restored
        assertEq(token.owner(), owner, "Owner should be reestablished after successful unlock");
    }

    function test_unauthorizedUnlockAttempt() public {
        // Owner locks contract
        vm.prank(owner);
        token.lock(1 days);

        // Attacker tries to unlock (with sufficient time passed)
        vm.warp(block.timestamp + 1 days + 1 seconds);
        vm.prank(attacker);
        vm.expectRevert("You don't have permission to unlock");
        token.unlock();

        // Contract remains locked
        assertEq(token.owner(), address(0), "Contract should remain locked after unauthorized access");
    }

    function test_lockedContractFunctionality() public {
        // Owner locks contract
        vm.prank(owner);
        token.lock(365 days);

        // Verify owner-only functions become inaccessible
        vm.expectRevert("Ownable: caller is not the owner");
        token.excludeFromFee(address(0x123));
    }
}
